const today = new Date().toLocaleDateString('pt-BR');
const KW = ['ceo','cto','coo','diretor','diretora','head','gerente','coordenador','coordenadora','gestor','gestora','lider','lideranca','cultural','museu','curador','curadoria','sesc','senac','senai','fundacao','secretaria','ong','audiovisual','video','motion','editor','criacao','criativo','inovacao','imersiv','imersao','professor','professora','instrutor','instrutora','docente','facilitador','tutor','tutora','conteudista','coach','mentor','palestrante','consultor','consultora','inteligencia','chatgpt','automacao','generativa','realidade','metaverso','gamificacao','interativo','cinematic','imersivo','game','design','designer','produtor','produtora','producao','diretoria','executivo','executiva','superintendente','vr','xr','immersive','creative','producer','filmmaker','director','manager','teacher','educador','educadora','ensino','pedagogico','pedagogica'];
const cvLinks = {
  'Diretor/Gestao': { name: 'CV Diretor Projetos Imersivos', url: 'https://drive.google.com/file/d/1jY44AW6htFtIW9gQbiIdL74mr_ERVFfT/view' },
  'IA/Tech': { name: 'CV Gestor IA & Automacao', url: 'https://drive.google.com/file/d/1U9SKqBZgLs0o7nQI9R0iq9ENZlOY43aD/view' },
  'Audiovisual/VR': { name: 'CV Diretor Audiovisual VR 360', url: 'https://drive.google.com/file/d/1QvxavvsSrNTYXr30jFvY44Yr8R1iMidf/view' },
  'Cultural/Museu': { name: 'CV Produtor Cultural', url: 'https://drive.google.com/file/d/1DM2TSU_5_zfdENoN2euD8c62geYq8hRx/view' },
  'Educacao/Professor': { name: 'CV Professor/Instrutor EAD', url: 'https://drive.google.com/file/d/1BnpOdQuIb3EoPFLdkLVXictdNxYN3iKJ/view' }
};
function dn(x){ if (x && typeof x === 'object') return x.display_name || x.name || ''; return x || ''; }
function words(tx){ return tx.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean); }
function matchAny(tx, list){ const w = words(tx); return list.some(function(kw){ return kw.indexOf(' ')>=0 ? tx.toLowerCase().indexOf(kw)>=0 : w.indexOf(kw)>=0; }); }
let all = [];
for (const item of $input.all()) {
  const raw = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json);
  if (raw.includes('Blocked') && raw.includes('Indeed')) continue;
  const rss = raw.match(/<item>[\s\S]*?<\/item>/g) || [];
  for (const r of rss) {
    const tm = r.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) || r.match(/<title>([^<]*)<\/title>/) || [];
    const t = tm[1] || '';
    const lm = r.match(/<link>([^<]*)<\/link>/) || [];
    const dm = r.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) || r.match(/<description>([^<]*)<\/description>/) || [];
    const d = (dm[1] || '').replace(/<[^>]+>/g,'').substring(0,160).trim();
    if (t) all.push({ title: t.trim(), link: (lm[1]||'').trim(), desc: d, src: 'Remoto' });
  }
  try {
    const js = JSON.parse(raw);
    const arr = Array.isArray(js) ? js : (js.results || js.data || js.jobs || []);
    for (const j of arr) {
      if (!j || typeof j !== 'object') continue;
      const t = j.title || j.name || j.position || '';
      const company = dn(j.company) || j.careerPageName || j.companyName || '';
      const city = dn(j.location) || j.city || j.candidate_required_location || '';
      const link = j.redirect_url || j.jobUrl || j.careerPageUrl || j.url || j.apply_url || '#';
      const isAdz = !!j.redirect_url;
      const isGupy = !isAdz && (!!j.careerPageName || !!j.careerPageUrl);
      if (t) all.push({ title: String(t), link: String(link), desc: [company, city].filter(Boolean).join(' - ').substring(0,160), src: isAdz ? 'Adzuna' : (isGupy ? 'Gupy' : 'API') });
    }
  } catch(e) {}
}
function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const seen = new Set();
const dedup = all.filter(function(j) { const k = j.title.toLowerCase().trim(); if (!k || seen.has(k)) return false; seen.add(k); return true; });
const filtered = dedup.filter(function(j) { return matchAny(j.title + ' ' + j.desc, KW); });
let uniq = filtered;
if (!uniq.length) return [{ json: { subject: 'Radar Vagas ' + today + ' -- nenhuma vaga no perfil hoje', html: '<p>Nenhuma vaga compativel hoje. Roda de novo amanha as 8h.</p>', count: 0 } }];
const cats = {
  'Diretor/Gestao': ['ceo','cto','coo','diretor','diretora','diretoria','head','chief','gerente','coordenador','coordenadora','gestor','gestora','lider','lideranca','superintendente','executivo','executiva','director','manager'],
  'IA/Tech': ['inteligencia','chatgpt','automacao','generativa','tecnologia'],
  'Audiovisual/VR': ['audiovisual','video','motion','editor','cinematic','realidade','vr','xr','metaverso','gamificacao','imersiv','imersao','imersivo','game','producer','filmmaker','creative','design','designer'],
  'Cultural/Museu': ['cultural','museu','curador','curadoria','sesc','senac','senai','fundacao','secretaria','ong','produtor','produtora'],
  'Educacao/Professor': ['professor','professora','instrutor','instrutora','docente','facilitador','tutor','tutora','conteudista','coach','mentor','palestrante','educador','educadora','ensino','pedagogico','pedagogica','teacher'],
  'Outros': ['consultor','consultora','producao','criacao','criativo','inovacao','interativo']
};
function cat(job) {
  const tx = job.title + ' ' + job.desc;
  for (const c in cats) { if (matchAny(tx, cats[c])) return c; }
  return 'Outros';
}
const grp = {};
const slice = uniq.slice(0, 250);
for (let i = 0; i < slice.length; i++) { const c = cat(slice[i]); if (!grp[c]) grp[c] = []; grp[c].push(slice[i]); }
const sc = { Adzuna: '#7b2ff7', Gupy: '#27ae60', Remoto: '#4A90E2', API: '#999' };
let html = '<div style="font-family:Arial,sans-serif;max-width:700px;"><h2 style="color:#1a1a2e;border-bottom:2px solid #7b2ff7;padding-bottom:8px;">Radar de Vagas -- ' + today + '</h2><p><strong>' + uniq.length + ' vagas</strong> | ' + Object.keys(grp).length + ' categorias</p><hr/>';
for (const c in grp) {
  const jobs = grp[c]; if (!jobs || !jobs.length) continue;
  html += '<h3 style="color:#7b2ff7;margin-top:20px;">' + c + ' (' + jobs.length + ')</h3>';
  const cvL = cvLinks[c];
  if (cvL) html += '<p style="margin-top:-8px;margin-bottom:12px;font-size:12px;">CV sugerido: <a href="' + cvL.url + '" style="color:#1B3A5C;font-weight:bold;">' + cvL.name + '</a> | <a href="https://azimutimmersive.com" style="color:#1B3A5C;">Portfolio</a></p>';
  for (let i = 0; i < jobs.length; i++) {
    const j = jobs[i]; const col = sc[j.src] || '#999';
    html += '<div style="margin-bottom:10px;padding:10px;border-left:3px solid ' + col + ';background:#f9f9f9;"><a href="' + esc(j.link) + '" style="font-weight:bold;color:#1a1a2e;">' + esc(j.title) + '</a> <span style="font-size:10px;color:#fff;background:' + col + ';padding:1px 5px;border-radius:3px;">' + j.src + '</span>';
    if (j.desc) html += '<br/><span style="font-size:12px;color:#444;">' + esc(j.desc) + '</span>';
    html += '</div>';
  }
}
html += '<hr/><div style="font-size:11px;color:#888;padding:8px 0;">CVs: <a href="https://drive.google.com/file/d/1jY44AW6htFtIW9gQbiIdL74mr_ERVFfT/view">Diretor Imersivo</a> - <a href="https://drive.google.com/file/d/1QvxavvsSrNTYXr30jFvY44Yr8R1iMidf/view">Audiovisual VR360</a> - <a href="https://drive.google.com/file/d/1BnpOdQuIb3EoPFLdkLVXictdNxYN3iKJ/view">Professor EAD</a> - <a href="https://drive.google.com/file/d/1U9SKqBZgLs0o7nQI9R0iq9ENZlOY43aD/view">Gestor IA</a> - <a href="https://drive.google.com/file/d/1DM2TSU_5_zfdENoN2euD8c62geYq8hRx/view">Produtor Cultural</a><br/>Portfolio: <a href="https://azimutimmersive.com">azimutimmersive.com</a></div>';
html += '<p style="font-size:11px;color:#aaa;">Radar Ranz v27 -- ' + today + ' -- ' + uniq.length + ' vagas</p></div>';
return [{ json: { subject: 'Radar Vagas ' + today + ' -- ' + uniq.length + ' vagas', html: html, count: uniq.length } }];
